const D = { scale:1, energy:.7, hue:315, speed:1, density:.5, x:.5, y:.72, pose:'cycle', style:'wildstyle', seed:0, act:'battle' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---------- frame + rhythm ----------
const u = Math.min(width, height);
const BS = 1.28;
const sc = (u/600) * P.scale * BS;
const ax = P.x*width, ay = P.y*height;
const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7) * 43758.5453; return s - Math.floor(s); };
if (S.lastBeat == null || K.beat < S.lastBeat) S.lastBeat = K.beat;
S.lastBeat = K.beat;
const H = ((P.hue%360)+360)%360;
const e = P.energy;
const bt = K.beat * P.speed;
const ph = K.phase;
const bounce = Math.sin(ph*Math.PI);
const kick = Math.min(1, K.pulse*(0.55+0.45*K.intensity) + A.bass*0.6);

// seed-keyed splats
if (S.seedUsed !== P.seed){ S.seedUsed=P.seed; S.splat=[]; for(let i=0;i<26;i++) S.splat.push({a:fr(i*5+1)*6.283, r:fr(i*5+2), s:fr(i*5+3), h:fr(i*5+4), w:fr(i*5+5)}); }

// ---------- act / choreography ----------
// pose cycle: each pose holds ~4 beats (one bar). act tweaks the setlist + feel.
const setBattle = ['top','foot','mill','freeze','top','mill','foot','freeze'];
const setCypher = ['top','foot','top','mill','foot','top','freeze','foot'];
const setlist = P.act==='cypher' ? setCypher : setBattle;
const phrase = Math.floor(bt/4);
let poseName = P.pose;
if (P.pose==='cycle') poseName = setlist[((phrase%setlist.length)+setlist.length)%setlist.length];
const inBeat = ((bt%4)+4)%4;           // 0..4 within the pose window
const settle = Math.min(1, inBeat*1.6); // ease into a new move

// ---------- style discipline ----------
let inkC, fillC, hiC, accC, paperC, lw, drip, spray, chrome=false, stencil=false, glitch=false, wild=false;
if (P.style==='stencil'){ paperC=[H,20,92]; inkC=[H,15,10]; fillC=[H,15,10]; hiC=[H,15,10]; accC=[(H+40)%360,70,90]; lw=0; drip=0; spray=1; stencil=true; }
else if (P.style==='chrome'){ paperC=[(H+200)%360,40,12]; inkC=[H,80,6]; fillC=[H,8,80]; hiC=[H,5,100]; accC=[(H+30)%360,90,96]; lw=4; drip=.4; spray=.5; chrome=true; }
else if (P.style==='glitch'){ paperC=[H,50,10]; inkC=[(H+180)%360,90,100]; fillC=[H,85,88]; hiC=[(H+150)%360,80,100]; accC=[(H+90)%360,85,96]; lw=2; drip=0; spray=.3; glitch=true; }
else if (P.style==='neon'){ paperC=[H,60,7]; inkC=[H,90,100]; fillC=[H,80,18]; hiC=[(H+40)%360,90,100]; accC=[(H+140)%360,85,100]; lw=3.4; drip=.2; spray=.4; }
else { paperC=[(H+18)%360,30,14]; inkC=[H,85,10]; fillC=[H,88,90]; hiC=[(H+22)%360,90,100]; accC=[(H+160)%360,80,92]; lw=5; drip=1; spray=1; wild=true; }
const F=c=>fill(c[0],c[1],c[2]);
const Fa=(c,a)=>fill(c[0],c[1],c[2],a);
const SK=(c,w)=>{ if(w>0){stroke(c[0],c[1],c[2]);strokeWeight(w);} else noStroke(); };

// ---------- cached graffiti wall ----------
const bKey = width+'x'+height+'|'+P.style+'|'+Math.round(H)+'|'+P.seed+'|'+Math.round(P.density*10)+'|'+Math.round(P.scale*20);
if (!S.wall || S.wallKey!==bKey){
  S.wallKey=bKey;
  const side=Math.max(64,Math.min(1100,Math.round(560*sc)));
  if (S.wall&&S.wall.remove) S.wall.remove();
  S.wall=createGraphics(side,side);
  const g=S.wall; g.colorMode(HSB,360,100,100,100); g.noStroke();
  g.fill(paperC[0],paperC[1],paperC[2],100); g.rect(0,0,side,side);
  if (stencil){
    for(let i=0;i<420;i++){ const d=fr(i*3)*side, dy=fr(i*3+1)*side, rr=fr(i*3+2); g.fill(inkC[0],inkC[1],inkC[2], rr*rr*20); g.circle(d,dy,1+rr*3); }
  } else if (glitch){
    for(let i=0;i<60;i++){ const yy=fr(i*2)*side, hh=2+fr(i*2+1)*10; g.fill((H+fr(i)*160)%360,80,90,8+fr(i*3)*14); g.rect(0,yy,side,hh); }
  } else {
    // spray-fog blobs + tag scrawls
