  for(let i=0;i<300;i++){ g.fill(0,0,0,6+fr(i*2)*10); g.circle(fr(i*7)*side,fr(i*7+3)*side,1+fr(i*7+5)*1.5); }
}

// ---------- geometry helpers ----------
const P2=(a,l)=>[Math.cos(a)*l, Math.sin(a)*l];
function capsule(x1,y1,x2,y2,w1,w2,c,outline){
  const dx=x2-x1,dy=y2-y1,d=Math.max(0.001,Math.sqrt(dx*dx+dy*dy)),nx=-dy/d,ny=dx/d;
  if (outline && lw>0){ SK(inkC,w1*2+lw*1.6); strokeCap(ROUND); line(x1,y1,x2,y2); }
  F(c); noStroke();
  beginShape(); vertex(x1+nx*w1,y1+ny*w1); vertex(x2+nx*w2,y2+ny*w2); vertex(x2-nx*w2,y2-ny*w2); vertex(x1-nx*w1,y1-ny*w1); endShape(CLOSE);
  noStroke();
}

// ---------- pose builder: joints in a frame whose origin is the pivot ----------
const UP=42,FO=38,TH=50,SH=48;         // limb lengths
function poseJoints(name){
  const b=inBeat, sw=Math.sin(bt*Math.PI*2/2), sw2=Math.sin(bt*Math.PI*2);
  let tilt=0, spin=0, lift=0, smear=0;
  let pv,nk,hd, sL,sR, hipL,hipR, aUL,aEL, aUR,aER, lUL,lEL, lUR,lER;
  if (name==='foot'){
    // six-step footwork: crouched, one hand plants, legs sweep in a circle
    lift=0; tilt=0.12*Math.sin(bt*Math.PI*2/4);
    const swp = bt*Math.PI*2*0.5;                 // legs orbit
    pv=[0,-58]; nk=[-6,-104]; hd=[-10,-128];
    sL=[-30,-98]; sR=[18,-100]; hipL=[-14,-54]; hipR=[14,-54];
    aUL=Math.PI*0.62; aEL=0.3;                    // left arm plants to floor
    aUR=Math.PI*0.2+sw*0.3; aER=0.5;
    lUL=Math.PI*0.06+Math.sin(swp)*0.5; lEL=0.7;  // sweeping legs
    lUR=Math.PI*0.9+Math.sin(swp+2.2)*0.5; lER=-0.6;
    smear=0.5;
  } else if (name==='mill'){
    // windmill: legs in a wide V, whole body spins around the low back
    lift=-40; spin = bt*Math.PI*(1.7+e*1.3);      // continuous spin (fast)
    smear=1;
    pv=[0,4]; nk=[2,-30]; hd=[6,-52];
    sL=[-24,-24]; sR=[24,-18]; hipL=[-12,20]; hipR=[12,20];
    aUL=Math.PI*0.9; aEL=0.4; aUR=Math.PI*0.1; aER=-0.4;
    lUL=-0.55; lEL=0.12;                          // legs kick out straight, wide V
    lUR=Math.PI-0.55; lER=-0.12;
  } else if (name==='freeze'){
    // baby/air freeze: planted on one hand, body angled, legs locked angular
    const trem=Math.sin(bt*Math.PI*2*3)*0.02*(1-settle*0.6)+Math.sin(bt*Math.PI*2)*0.015;
    tilt=-0.62+trem; lift=-6; smear=0.1;
    pv=[0,-40]; nk=[-30,-58]; hd=[-52,-64];
    sL=[-44,-46]; sR=[-10,-64]; hipL=[10,-26]; hipR=[18,-40];
    aUL=Math.PI*0.52; aEL=0.15;                   // support arm straight to floor
    aUR=Math.PI*0.85; aER=1.0;                    // other elbow braces hip
    lUL=-0.35; lEL=1.1;                           // bent knee tucked
    lUR=-0.9; lER=0.2;                            // top leg locked out
  } else {
    // toprock: upright, bouncing, cross-step, arms swinging
    const step=Math.sin(bt*Math.PI*2/2);
    lift=-bounce*(6+9*e)-Math.abs(sw2)*3; tilt=step*0.08; smear=0.2;
    pv=[step*6,-92]; nk=[step*4,-150]; hd=[step*3,-180];
    sL=[-28,-146]; sR=[28,-146]; hipL=[-16,-88]; hipR=[16,-88];
    aUL=Math.PI*0.62+step*0.5; aEL=-0.7+step*0.4;   // arms swing across body
    aUR=Math.PI*0.38-step*0.5; aER=0.7-step*0.4;
    lUL=Math.PI*0.5-0.14+step*0.22; lEL=0.26;        // stepping legs
    lUR=Math.PI*0.5+0.14+step*0.22; lER=-0.26;
  }
  // forward kinematics
  const eL=[sL[0]+P2(aUL,UP)[0], sL[1]+P2(aUL,UP)[1]];
  const wL=[eL[0]+P2(aUL+aEL,FO)[0], eL[1]+P2(aUL+aEL,FO)[1]];
  const eR=[sR[0]+P2(aUR,UP)[0], sR[1]+P2(aUR,UP)[1]];
  const wR=[eR[0]+P2(aUR+aER,FO)[0], eR[1]+P2(aUR+aER,FO)[1]];
  const kL=[hipL[0]+P2(lUL,TH)[0], hipL[1]+P2(lUL,TH)[1]];
  const fL=[kL[0]+P2(lUL+lEL,SH)[0], kL[1]+P2(lUL+lEL,SH)[1]];
  const kR=[hipR[0]+P2(lUR,TH)[0], hipR[1]+P2(lUR,TH)[1]];
  const fR=[kR[0]+P2(lUR+lER,SH)[0], kR[1]+P2(lUR+lER,SH)[1]];
  return {pv,nk,hd,sL,sR,hipL,hipR,eL,wL,eR,wR,kL,fL,kR,fR,tilt,spin,lift,smear};
}

function drawFigure(J, alpha, ghost){
  push();
  translate(0, J.lift);
  rotate(J.tilt + J.spin);
  const fc = ghost ? accC : fillC;
  const skC = ghost ? accC : hiC;
  // back leg + arm first
  capsule(J.hipR[0],J.hipR[1],J.kR[0],J.kR[1],15,12,fc,!ghost);
  capsule(J.kR[0],J.kR[1],J.fR[0],J.fR[1],12,7,fc,!ghost);
  capsule(J.sR[0],J.sR[1],J.eR[0],J.eR[1],11,9,fc,!ghost);
  capsule(J.eR[0],J.eR[1],J.wR[0],J.wR[1],9,6,fc,!ghost);
  if(!ghost){ F(skC); noStroke(); circle(J.fR[0],J.fR[1],17); circle(J.wR[0],J.wR[1],12); }
  // torso mass
  if (lw>0 && !ghost){ SK(inkC, lw*1.6); }
  F(fc); if(lw>0&&!ghost){stroke(inkC[0],inkC[1],inkC[2]);strokeWeight(lw);}else noStroke();
  beginShape(); vertex(J.sL[0],J.sL[1]); vertex(J.sR[0],J.sR[1]); vertex(J.hipR[0]+6,J.hipR[1]); vertex(J.hipL[0]-6,J.hipL[1]); endShape(CLOSE);
  if (chrome && !ghost){ noStroke(); Fa(hiC,60); beginShape(); vertex(J.sL[0],J.sL[1]); vertex((J.sL[0]+J.sR[0])/2,J.sR[1]); vertex((J.hipL[0]+J.hipR[0])/2,J.hipR[1]); vertex(J.hipL[0]-6,J.hipL[1]); endShape(CLOSE); }
  if (glitch && !ghost){ noStroke(); Fa(hiC,60); rect(J.sL[0],J.nk[1],Math.abs(J.sR[0]-J.sL[0]),6); }
  // head
  push(); translate(J.hd[0],J.hd[1]);
  if(lw>0&&!ghost){SK(inkC,lw);}else noStroke();
  F(ghost?accC:fillC); ellipse(0,0,50,54);
  if(!ghost){
    F(hiC); noStroke(); arc(0,-4,50,54,Math.PI*1.15,Math.PI*1.95);   // cap / hair mass
    if(!stencil){ Fa(inkC,90); rect(-16,-4,32,7,3); }                // brow-bar (no cartoon eyes)
    F(skC); ellipse(-9,4,9,6);                                       // cheek highlight
  }
  pop();
  // front leg + arm
  capsule(J.hipL[0],J.hipL[1],J.kL[0],J.kL[1],15,12,fc,!ghost);
  capsule(J.kL[0],J.kL[1],J.fL[0],J.fL[1],12,7,fc,!ghost);
  capsule(J.sL[0],J.sL[1],J.eL[0],J.eL[1],11,9,fc,!ghost);
  capsule(J.eL[0],J.eL[1],J.wL[0],J.wL[1],9,6,fc,!ghost);
  if(!ghost){ F(skC); noStroke(); circle(J.fL[0],J.fL[1],17); circle(J.wL[0],J.wL[1],12); }
  pop();
}

// =============== DRAW ===============
push();
translate(ax, ay);
scale(sc);

// wall backdrop
push(); translate(0,-150); rotate(Math.sin(K.t*0.04)*0.02);
imageMode(CENTER); image(S.wall,0,0,560,560); imageMode(CORNER); pop();
// floor shadow (breathes)
noStroke(); Fa([0,0,0],26); ellipse(0,4,300+kick*30,30);

const J = poseJoints(poseName);

// motion-smear arcs — ghost copies of a spinning/sweeping body
const smearN = Math.round((2+P.density*4) * J.smear * (0.5+e*0.5));
if (smearN>0){
  blendMode(ADD);
  for(let i=1;i<=smearN;i++){
    const back = i*0.16*(1+e);
    const G = {...J, spin: J.spin - back*(J.spin!==0?1:0), tilt: J.tilt - (J.spin===0?back*0.4:0)};
    // ghost draws only limbs, translucent accent
    push(); translate(0,J.lift); rotate(G.tilt + G.spin);
    Fa(accC, 30*(1-i/(smearN+1)));
    // sweep limbs as accent streaks
    const seg=(a,b,w)=>{ SK(false,0); F(accC); const dx=b[0]-a[0],dy=b[1]-a[1],d=Math.max(0.01,Math.sqrt(dx*dx+dy*dy)),nx=-dy/d,ny=dx/d; Fa(accC,30*(1-i/(smearN+1))); beginShape(); vertex(a[0]+nx*w,a[1]+ny*w); vertex(b[0]+nx*w*0.6,b[1]+ny*w*0.6); vertex(b[0]-nx*w*0.6,b[1]-ny*w*0.6); vertex(a[0]-nx*w,a[1]-ny*w); endShape(CLOSE); };
    seg(J.hipR,J.fR,11); seg(J.hipL,J.fL,11); seg(J.sR,J.wR,8); seg(J.sL,J.wL,8);
    pop();
  }
  blendMode(BLEND);
}

// paint splats flung on strong beats
if (spray>0){ noStroke(); const sn=Math.round((4+P.density*14)*spray);
  for(let i=0;i<sn;i++){ const sp=S.splat[i%S.splat.length]; const life=((bt*0.3+sp.s)%1+1)%1;
    const rad=(120+sp.r*160); const cx=Math.cos(sp.a)*rad*(0.4+life*0.9), cy=Math.sin(sp.a)*rad*(0.4+life*0.9)-60;
    const cc= sp.h<0.5?accC:hiC; Fa(cc,(1-life)*70); circle(cx,cy, (2+sp.w*8)*(1-life*0.5));
    if(drip>0 && sp.w>0.6){ Fa(cc,(1-life)*50); rect(cx-1.2, cy, 2.4, 6+sp.w*16*drip, 2); }
  }
}

// the dancer
drawFigure(J, 1, false);

// glitch RGB-split overlay pass
if (glitch){ blendMode(ADD);
  push(); translate(3+Math.sin(K.t*7)*2, 0); Fa([0,90,90],14);
  drawFigure(poseJoints(poseName), 1, true); pop();
  blendMode(BLEND);
}

// neon rim on dark styles
if (P.style==='neon'){ blendMode(ADD);
  drawingContext.shadowBlur=18; drawingContext.shadowColor='rgba(255,80,220,0.7)';
  SK(inkC,2.4); noFill();
  beginShape(); vertex(J.sL[0],J.sL[1]); vertex(J.sR[0],J.sR[1]); vertex(J.hipR[0]+6,J.hipR[1]); vertex(J.hipL[0]-6,J.hipL[1]); endShape(CLOSE);
  drawingContext.shadowBlur=0; blendMode(BLEND);
}

